export interface RuntimeMetrics {
  queueDepth: number;
  pendingTurns: number;
  activeTurns: number;
  agentActions: number;
  buildActions: number;
  sessionMetrics: {
    seed: number | null;
    phase: SessionPhase;
    tick: number;
    paused: boolean;
  };
}

export class MetricsCollector {
  private metrics: RuntimeMetrics = {
    queueDepth: 0,
    pendingTurns: 0,
    activeTurns: 0,
    agentActions: 0,
    buildActions: 0,
    sessionMetrics: {
      seed: null,
      phase: "idle",
      tick: 0,
      paused: false
    }
  };

  updateQueueDepth(depth: number): void {
    this.metrics.queueDepth = depth;
  }

  updatePendingTurns(count: number): void {
    this.metrics.pendingTurns = count;
  }

  updateActiveTurns(count: number): void {
    this.metrics.activeTurns = count;
  }

  updateAgentActions(count: number): void {
    this.metrics.agentActions = count;
  }

  updateBuildActions(count: number): void {
    this.metrics.buildActions = count;
  }

  updateSessionMetrics(metrics: Omit<RuntimeMetrics["sessionMetrics"], "seed">): void {
    this.metrics.sessionMetrics = {
      ...this.metrics.sessionMetrics,
      ...metrics
    };
  }

  snapshot(): RuntimeMetrics {
    return { ...this.metrics };
  }
}
```

